@startuml

class Center {
  + Name : string
  + Address : string
}

class Room {
  + Number : int
  + MaxCapacity : int
}

class Person {
  + FirstName : string
  + FamilyName : string
  + BirthDate : date
}

class Trainer extends Person {
  + Diploma : string
}

class Session {
  + Date : date
  + StartingHour : time
}

class GroupSession extends Session {
  + Type : string
}

class IndividualSession extends Session {
}

class Participation {
}

class Supervision {
}

Center "1" *-- "1..*" Room
Center "1" -- "0..*" Session
Room "1" -- "0..*" Session
Person "0..*" -- "0..*" Session : Participation
Trainer "0..1" -- "0..*" Session : Supervision

@enduml

